    ox = 0 if ox < 0 else (w - 1 if ox >= w else ox)
    oy = 0 if oy < 0 else (h - 1 if oy >= h else oy)

    obstacles = set()
    for p in (observation.get("obstacles") or []):
        try:
            x, y = int(p[0]), int(p[1])
            if 0 <= x < w and 0 <= y < h:
                obstacles.add((x, y))
        except:
            pass

    resources = []
    for r in (observation.get("resources") or []):
        try:
            x, y = int(r[0]), int(r[1])
            if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
                resources.append((x, y))
        except:
            pass

    def bfs(start):
        INF = 10**9
        dist = [[INF] * h for _ in range(w)]
        x0, y0 = start
        if (x0, y0) in obstacles:
            return dist
        qx = [x0]; qy = [y0]; head = 0
        dist[x0][y0] = 0
        while head < len(qx):
            x, y = qx[head], qy[head]; head += 1
            d = dist[x][y] + 1
            for dx in (-1, 0, 1):
                nx = x + dx
                if nx < 0 or nx >= w: 
                    continue
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    ny = y + dy
                    if ny < 0 or ny >= h or (nx, ny) in obstacles:
                        continue
                    if d < dist[nx][ny]:
                        dist[nx][ny] = d
                        qx.append(nx); qy.append(ny)
        return dist

    dself = bfs((sx, sy))
    dopt = bfs((ox, oy))

    if not resources:
        return [0, 0]

    best = None
    best_key = None
    for rx, ry in resources:
        ds = dself[rx][ry]
        do = dopt[rx][ry]
        if ds >= 10**8 and do >= 10**8:
            continue
        key = (do - ds, -ds, -rx, -ry)
        if best_key is None or key > best_key:
            best_key = key
            best = (rx, ry)

    tx, ty = best
    moves = []
    for dx in (-1, 0, 1):
        nx = sx + dx
        if nx < 0 or nx >= w:
            continue
        for dy in (-1, 0, 1):
            ny = sy + dy
            if ny < 0 or ny >= h or (nx, ny) in obstacles:
                continue
            moves.append((dx, dy, dself[nx][ny], dopt[nx][ny]))
    if not moves:
        return [0, 0]

    # Prefer reducing distance to target; secondarily reduce opponent distance after tie.
    moves.sort(key=lambda m: (abs((m[2] - dself[tx][ty])) , m[2], -(m[3]), m[0], m[1]))
    dx, dy = moves[0][0], moves[0][1]
    return [int(dx), int(dy)]

